// Choose a valid profile randomly
unsigned int profile_idx = *FUZZ_PARAM(unsigned int) % 4; // 0..3
astcenc_profile profile = static_cast<astcenc_profile>(profile_idx);

// Choose a commonly valid block size triplet from the ASTC spec
struct BX { unsigned int x,y,z; };
const BX kBlocks[] = {
    {4,4,1}, {5,4,1}, {5,5,1}, {6,5,1}, {6,6,1},
    {8,5,1}, {8,6,1}, {8,8,1}, {10,5,1}, {10,6,1},
    {10,8,1}, {10,10,1}, {12,10,1}, {12,12,1},
    {3,3,3}, {4,3,3}, {4,4,3}, {4,4,4}
};
const BX sel = kBlocks[*FUZZ_PARAM(unsigned int) % (sizeof(kBlocks)/sizeof(kBlocks[0]))];
unsigned int block_x = sel.x;
unsigned int block_y = sel.y;
unsigned int block_z = sel.z;

// Quality in [0,100]
float quality = static_cast<float>(*FUZZ_PARAM(unsigned int) % 101);

// Flags: use 0 to avoid unknown/unsupported bits
unsigned int flags = 0u;

// Prepare writable config pointer
astcenc_config* config = new astcenc_config();

// Invoke API and validate
astcenc_error st = astcenc_config_init(profile, block_x, block_y, block_z, quality, flags, config);
if (st != ASTCENC_SUCCESS) {
    // Do not leak on failure
    delete config;
    FUZZ_BAIL();
}

// Track attributes needed by later calls
FUZZ_SET_ATTR_INT(config, "init", 1);
FUZZ_SET_ATTR_INT(config, "block_x", (int)block_x);
FUZZ_SET_ATTR_INT(config, "block_y", (int)block_y);
FUZZ_SET_ATTR_INT(config, "block_z", (int)block_z);
FUZZ_SET_ATTR_INT(config, "flags", (int)flags);
FUZZ_SET_ATTR_INT(config, "profile", (int)profile);

// Provide config as persistent output

// Ensure the config was initialized via astcenc_config_init
if (FUZZ_GET_ATTR_INT(config, "init") != 1) { FUZZ_BAIL(); }

// Thread count: small, >0
unsigned int thread_count = (*FUZZ_PARAM(unsigned int) % 4) + 1; // 1..4

astcenc_context* context = nullptr;
astcenc_error st = astcenc_context_alloc(config, thread_count, &context);
if (st != ASTCENC_SUCCESS || !context) { FUZZ_BAIL(); }

// Propagate key attributes from config to context for later validation
FUZZ_SET_ATTR_INT(context, "thread_count", (int)thread_count);
FUZZ_SET_ATTR_INT(context, "block_x", FUZZ_GET_ATTR_INT(config, "block_x"));
FUZZ_SET_ATTR_INT(context, "block_y", FUZZ_GET_ATTR_INT(config, "block_y"));
FUZZ_SET_ATTR_INT(context, "block_z", FUZZ_GET_ATTR_INT(config, "block_z"));
FUZZ_SET_ATTR_INT(context, "profile", FUZZ_GET_ATTR_INT(config, "profile"));

// Return both config (still user-owned/persistent) and the new context

// Retrieve required context attributes
int bx = FUZZ_GET_ATTR_INT(context, "block_x");
int by = FUZZ_GET_ATTR_INT(context, "block_y");
int bz = FUZZ_GET_ATTR_INT(context, "block_z");
if (bx <= 0 || by <= 0 || bz <= 0) { FUZZ_BAIL(); }
int thread_count = FUZZ_GET_ATTR_INT(context, "thread_count");
if (thread_count <= 0) { thread_count = 1; }

// Choose small image dims to keep memory bounded
unsigned int dim_z = (bz == 1) ? 1u : (unsigned int)((*FUZZ_PARAM(unsigned int) % 2) + 1); // 1..2 for 3D, else 1
unsigned int dim_x = (unsigned int)((*FUZZ_PARAM(unsigned int) % 32) + 1); // 1..32
unsigned int dim_y = (unsigned int)((*FUZZ_PARAM(unsigned int) % 32) + 1); // 1..32

// Pick a data type and compute per-texel bytes (4 components)
unsigned int dt_idx = *FUZZ_PARAM(unsigned int) % 3; // 0..2
astcenc_type dtype = static_cast<astcenc_type>(dt_idx);
unsigned int bpc = (dtype == ASTCENC_TYPE_U8) ? 1u : (dtype == ASTCENC_TYPE_F16 ? 2u : 4u);
size_t bytes_per_texel = 4u * bpc;

// Compute slice size and ensure it stays small
size_t slice_bytes = (size_t)dim_x * (size_t)dim_y * bytes_per_texel;
if (slice_bytes == 0 || slice_bytes > 2048) {
    // Constrain size: fallback to a tiny image compatible with block size
    dim_x = (unsigned int)((bx <= 4) ? 4 : (unsigned int)bx);
    dim_y = (unsigned int)((by <= 4) ? 4 : (unsigned int)by);
    dim_z = (unsigned int)((bz <= 1) ? 1 : (unsigned int)bz);
    slice_bytes = (size_t)dim_x * (size_t)dim_y * bytes_per_texel;
    if (slice_bytes == 0 || slice_bytes > 2048) { FUZZ_BAIL(); }
}

// Build image storage: data is an array of dim_z slices
std::vector<void*> slices;
slices.resize(dim_z, nullptr);
for (unsigned int z = 0; z < dim_z; ++z) {
    // Allocate and fill slice with fuzz data
    std::vector<uint8_t> tmp;
    tmp.resize(slice_bytes);
    std::string fuzz = FUZZ_PARAM_STR();
    for (size_t i = 0; i < slice_bytes; ++i) {
        tmp[i] = (uint8_t)fuzz[i % fuzz.size()];
    }
    // Materialize backing store per slice
    uint8_t* buf = new uint8_t[slice_bytes];
    std::memcpy(buf, tmp.data(), slice_bytes);
    slices[z] = buf;
}

astcenc_image img{};
img.dim_x = dim_x; img.dim_y = dim_y; img.dim_z = dim_z;
img.data_type = dtype;
img.data = (void**)slices.data();

// Build a valid swizzle
astcenc_swizzle swz{};
swz.r = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);
swz.g = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);
swz.b = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);
swz.a = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);

// Compute required compressed buffer size: 16 bytes per block
auto cdiv = [](unsigned int v, unsigned int d){ return (v + d - 1u) / d; };
size_t blocks = (size_t)cdiv(dim_x, (unsigned int)bx) * (size_t)cdiv(dim_y, (unsigned int)by) * (size_t)cdiv(dim_z, (unsigned int)bz);
size_t out_bytes = blocks * 16u;
if (out_bytes == 0) { FUZZ_BAIL(); }
std::vector<uint8_t> out;
out.resize(out_bytes);

// Thread index in-range
unsigned int thread_index = (thread_count > 0) ? (*FUZZ_PARAM(unsigned int) % (unsigned int)thread_count) : 0u;

astcenc_error st = astcenc_compress_image(context, &img, &swz, out.data(), out.size(), thread_index);
if (st != ASTCENC_SUCCESS) {
    // Clean up slices before bailing
    for (void* p : slices) { delete[] (uint8_t*)p; }
    FUZZ_BAIL();
}

// Clean up temporary image buffers (API does not take ownership)
for (void* p : slices) { delete[] (uint8_t*)p; }

// Return context as persistent output

// Reset compression state between images; caller must ensure threads are quiesced.
astcenc_error st = astcenc_compress_reset(context);
if (st != ASTCENC_SUCCESS) { FUZZ_BAIL(); }
// Context remains valid and is returned as output

// Request cancellation; must still follow normal reset/synchronization afterwards.
astcenc_error st = astcenc_compress_cancel(context);
if (st != ASTCENC_SUCCESS) { FUZZ_BAIL(); }
// Context persists

// Retrieve required context attributes
int bx = FUZZ_GET_ATTR_INT(context, "block_x");
int by = FUZZ_GET_ATTR_INT(context, "block_y");
int bz = FUZZ_GET_ATTR_INT(context, "block_z");
if (bx <= 0 || by <= 0 || bz <= 0) { FUZZ_BAIL(); }
int thread_count = FUZZ_GET_ATTR_INT(context, "thread_count");
if (thread_count <= 0) { thread_count = 1; }

// Choose small output image dims
unsigned int dim_z = (bz == 1) ? 1u : (unsigned int)((*FUZZ_PARAM(unsigned int) % 2) + 1);
unsigned int dim_x = (unsigned int)((*FUZZ_PARAM(unsigned int) % 32) + 1);
unsigned int dim_y = (unsigned int)((*FUZZ_PARAM(unsigned int) % 32) + 1);

// Pick output data type and bytes per texel
unsigned int dt_idx = *FUZZ_PARAM(unsigned int) % 3; // 0..2
astcenc_type dtype = static_cast<astcenc_type>(dt_idx);
unsigned int bpc = (dtype == ASTCENC_TYPE_U8) ? 1u : (dtype == ASTCENC_TYPE_F16 ? 2u : 4u);
size_t bytes_per_texel = 4u * bpc;

size_t slice_bytes = (size_t)dim_x * (size_t)dim_y * bytes_per_texel;
if (slice_bytes == 0 || slice_bytes > 2048) {
    dim_x = (unsigned int)((bx <= 4) ? 4 : (unsigned int)bx);
    dim_y = (unsigned int)((by <= 4) ? 4 : (unsigned int)by);
    dim_z = (unsigned int)((bz <= 1) ? 1 : (unsigned int)bz);
    slice_bytes = (size_t)dim_x * (size_t)dim_y * bytes_per_texel;
    if (slice_bytes == 0 || slice_bytes > 2048) { FUZZ_BAIL(); }
}

// Prepare output image buffer
std::vector<void*> slices;
slices.resize(dim_z, nullptr);
for (unsigned int z = 0; z < dim_z; ++z) {
    uint8_t* buf = new uint8_t[slice_bytes];
    // Initialize to fuzzed pattern for determinism under sanitizer
    std::string fuzz = FUZZ_PARAM_STR();
    for (size_t i = 0; i < slice_bytes; ++i) { buf[i] = (uint8_t)fuzz[i % fuzz.size()]; }
    slices[z] = buf;
}

astcenc_image out{};
out.dim_x = dim_x; out.dim_y = dim_y; out.dim_z = dim_z;
out.data_type = dtype;
out.data = (void**)slices.data();

// Compute required compressed data size and make a buffer of exactly that size
auto cdiv = [](unsigned int v, unsigned int d){ return (v + d - 1u) / d; };
size_t blocks = (size_t)cdiv(dim_x, (unsigned int)bx) * (size_t)cdiv(dim_y, (unsigned int)by) * (size_t)cdiv(dim_z, (unsigned int)bz);
size_t data_len = blocks * 16u;
if (data_len == 0) {
    for (void* p : slices) { delete[] (uint8_t*)p; }
    FUZZ_BAIL();
}
std::vector<uint8_t> data;
data.resize(data_len);
{
    std::string fuzz = FUZZ_PARAM_STR();
    for (size_t i = 0; i < data_len; ++i) { data[i] = (uint8_t)fuzz[i % fuzz.size()]; }
}

// Build a valid post-decode swizzle
astcenc_swizzle swz{};
swz.r = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);
swz.g = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);
swz.b = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);
swz.a = static_cast<astcenc_swz>(*FUZZ_PARAM(unsigned int) % 7);

unsigned int thread_index = (thread_count > 0) ? (*FUZZ_PARAM(unsigned int) % (unsigned int)thread_count) : 0u;
astcenc_error st = astcenc_decompress_image(context, data.data(), data.size(), &out, &swz, thread_index);

// Clean up temporary output buffers regardless of success
for (void* p : slices) { delete[] (uint8_t*)p; }

if (st != ASTCENC_SUCCESS) { FUZZ_BAIL(); }
