int by = FUZZ_GET_ATTR_INT(context, "block_y");
int bz = FUZZ_GET_ATTR_INT(context, "block_z");
int pr = FUZZ_GET_ATTR_INT(context, "profile");
if (bx <= 0 || by <= 0 || bz <= 0) { FUZZ_BAIL(); }

// Prepare exactly 16 bytes of block data using fuzzed content
uint8_t data[16];
{
    std::string s = FUZZ_PARAM_STR();
    // Wrap the fuzzed data to fill all 16 bytes
    for (int i = 0; i < 16; ++i) {
        data[i] = (uint8_t)s[i % s.size()];
    }
}

// Prepare an output info struct
astcenc_block_info info{};

// Invoke API
astcenc_error st = astcenc_get_block_info(context, data, &info);
if (st != ASTCENC_SUCCESS) { FUZZ_BAIL(); }

// Property checks: on success, block dimensions and profile should match context configuration
FUZZ_ASSERT((int)info.block_x == bx, "block_x mismatch with context");
FUZZ_ASSERT((int)info.block_y == by, "block_y mismatch with context");
FUZZ_ASSERT((int)info.block_z == bz, "block_z mismatch with context");
FUZZ_ASSERT((int)info.profile == pr, "profile mismatch with context");

